import manifest from "@/data/image-manifest.json";
import { asset } from "./site";

export type ImageKey = keyof typeof manifest;

type Entry = { w: number; h: number; widths: number[] };

/** Responsive WebP sources generated by scripts/optimize_images.py into /public/images. */
export function responsiveImage(key: ImageKey) {
  const entry = manifest[key] as Entry;
  const src = (w: number) => asset(`/images/${key}-${w}.webp`);
  const largest = entry.widths[entry.widths.length - 1];
  return {
    src: src(entry.widths.length > 1 ? entry.widths[entry.widths.length - 2] : largest),
    srcSet: entry.widths.map((w) => `${src(w)} ${w}w`).join(", "),
    width: entry.w,
    height: entry.h,
  };
}
